"""Generate docs/data-dictionary.md from the dbt manifest (single source: the dbt YAML)."""

import json
from pathlib import Path
from typing import Any

LAYERS = [
    ("Marts (contract enforced)", "model", "marts"),
    ("Seeds (reference data)", "seed", None),
    ("Intermediate", "model", "intermediate"),
    ("Staging", "model", "staging"),
]

HEADER = """# Data dictionary

<!-- Generated by `hpdq docs` from the dbt manifest. Do not edit by hand: change the
     descriptions in dbt/models/**/*.yml or dbt/seeds/_seeds.yml and re-run. -->

Generated from the dbt project. Prices are integer rupiah per unit. Dates are WIB business dates.
Timestamps are UTC. Lineage: every fact row carries the `snapshot_id` of the raw file it came from.
"""


def _one_line(text: str | None) -> str:
    return " ".join((text or "").split()).replace("|", "\\|")


def _grains(manifest: dict[str, Any]) -> dict[str, list[str]]:
    grains: dict[str, list[str]] = {}
    for node in manifest["nodes"].values():
        meta = node.get("test_metadata") or {}
        if node["resource_type"] == "test" and meta.get("name") == "unique_combination":
            kwargs = meta.get("kwargs", {})
            combination = kwargs.get("combination") or kwargs.get("arguments", {}).get(
                "combination"
            )
            target = node.get("attached_node")
            if target and combination:
                grains[target] = list(combination)
    return grains


def _column_type(node: dict[str, Any], name: str, column: dict[str, Any]) -> str:
    declared = column.get("data_type")
    if declared:
        return str(declared)
    seed_types: dict[str, str] = node.get("config", {}).get("column_types") or {}
    return seed_types.get(name, "")


def render(manifest: dict[str, Any]) -> str:
    grains = _grains(manifest)
    nodes = sorted(manifest["nodes"].values(), key=lambda n: n["name"])
    out = [HEADER]
    for title, resource_type, folder in LAYERS:
        selected = [
            n
            for n in nodes
            if n["resource_type"] == resource_type
            and n["package_name"] == "hpdq"
            and (folder is None or n["fqn"][1:2] == [folder])
        ]
        if not selected:
            continue
        out.append(f"\n## {title}\n")
        for node in selected:
            out.append(f"\n### `{node['name']}`\n")
            if node.get("description"):
                out.append("\n" + _one_line(node["description"]) + "\n")
            grain = grains.get(node["unique_id"])
            if grain:
                times = " \N{MULTIPLICATION SIGN} "
                out.append(f"\n**Grain:** one row per {times.join(f'`{c}`' for c in grain)}.\n")
            columns = node.get("columns") or {}
            if columns:
                out.append("\n| Column | Type | Description |\n|---|---|---|\n")
                for name, column in columns.items():
                    out.append(
                        f"| `{name}` | {_column_type(node, name, column)} | "
                        f"{_one_line(column.get('description'))} |\n"
                    )
    return "".join(out)


def write_data_dictionary(manifest_path: Path, out_path: Path) -> Path:
    manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    out_path.parent.mkdir(parents=True, exist_ok=True)
    out_path.write_text(render(manifest), encoding="utf-8", newline="\n")
    return out_path
